class Cart {
  private appliedDiscount?: number;

  addItem(item: Item) { /* add item */ }

  prepareDiscount(customer: Customer) {
    this.appliedDiscount = computeDiscount(customer);
  }

  total(): number {
    const base = this.itemsTotal();
    return base - (this.appliedDiscount || 0);
  }
}

class InvoiceService {
  private tempTaxRate?: number;

  beginInvoice(customer: Customer) {
    this.tempTaxRate = lookupTax(customer.address);
  }

  computeTotal(items: Item[]) {
    const subtotal = sum(items);
    return subtotal * (1 + (this.tempTaxRate || 0));
  }

  completeInvoice() { this.tempTaxRate = undefined; }
}

// Version A
class OrderServiceA {
  private requestDiscount?: number;

  start(order: Order) { this.requestDiscount = calcDiscount(order); }
  apply(order: Order) { return order.total - (this.requestDiscount || 0); }
  finish() { this.requestDiscount = undefined; }
}

// Version B
class OrderServiceB {
  apply(order: Order) {
    const ctx = { discount: calcDiscount(order) };
    return order.total - ctx.discount;
  }
}
